document.addEventListener("DOMContentLoaded",()=>{const e=[{year:"1932",title:"The Birth of Tata Airlines",description:"J.R.D. Tata piloted the first flight from Karachi to Bombay in a single-engine De Havilland Puss Moth, carrying mail.",route:"Karachi → Ahmedabad → Bombay",showRoute:!0},{year:"1946",title:"Air India & The Maharaja",description:"Tata Airlines becomes a public limited company under the name Air India. The iconic Maharaja mascot is born.",route:"",showRoute:!1},{year:"1948",title:"First International Flight",description:'A Lockheed Constellation L-749 named "Malabar Princess" took off from Bombay to London, marking India\'s first international flight.',route:"Bombay → Cairo → Geneva → London",showRoute:!0},{year:"1953",title:"Nationalization",description:"The Government of India passed the Air Corporations Act, nationalizing the carrier as Air India International Limited.",route:"",showRoute:!1},{year:"1960",title:"The Jet Age Begins",description:'Air India enters the jet age with its first Boeing 707, named "Gauri Shankar", becoming the first Asian airline to operate a jet aircraft.',route:"Bombay → London → New York",showRoute:!0},{year:"1971",title:"The Jumbo Era",description:'Air India receives its first Boeing 747-200, "Emperor Ashoka", introducing a new era of luxury travel with "Palace in the Sky" livery.',route:"",showRoute:!1},{year:"2022",title:"Return to Tata",description:"After 69 years as a government-owned enterprise, Air India is officially handed back to the Tata Group, beginning a massive transformation journey.",route:"",showRoute:!1}],t=document.getElementById("timeline-events"),i=document.getElementById("detail-year"),n=document.getElementById("detail-title"),a=document.getElementById("detail-desc"),o=document.getElementById("route-map"),r=document.getElementById("route-info"),s=document.getElementById("timeline-details");function d(t){const d=e[t];d&&(document.querySelectorAll(".timeline-event").forEach(e=>e.classList.remove("active")),document.querySelector(`.timeline-event[data-index="${t}"]`).classList.add("active"),s.style.opacity="0",s.style.transform="translateY(10px)",setTimeout(()=>{i.textContent=d.year,n.textContent=d.title,a.textContent=d.description,d.showRoute?(r.textContent=d.route,o.style.display="flex"):o.style.display="none",s.style.opacity="1",s.style.transform="translateY(0)"},300))}t&&(e.forEach((e,i)=>{const n=document.createElement("div");n.className="timeline-event",n.dataset.index=i,n.innerHTML=`\n                <div class="event-year">${e.year}</div>\n                <div class="event-dot"></div>\n            `,n.addEventListener("click",()=>d(i)),t.appendChild(n)}),setTimeout(()=>d(0),500));const l=document.querySelector(".scroll-indicator");l&&l.addEventListener("click",()=>{window.scrollTo({top:window.innerHeight,behavior:"smooth"})})});